spec.css:
/* Lucky Rainbow: a night market of a theme. Every colour at once, a
   backdrop that never stops moving, and a lucky charm in front of anything
   that will hold still for one. Drawn in gradients and emoji, so the theme
   carries no file. */
@keyframes lucky-drift { to { background-position: 400% 50%; } }
@keyframes lucky-bob { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-4px); } }
@keyframes lucky-twinkle { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }
.bg-backdrop {
  background-image: linear-gradient(120deg, #ff9ff3, #ffd93d, #6bcb77, #4d96ff, #ff6b6b, #c77dff, #ff9ff3);
  background-size: 400% 400%;
  background-attachment: fixed;
  animation: lucky-drift 14s linear infinite;
}
[data-rail], [data-sidebar] {
  --color-surface: #ff2e88;
  --color-surface-raised: #ff5ca3;
  --color-border: #ffd600;
  --color-border-strong: #fff176;
  --color-ink: #ffffff;
  --color-ink-muted: #ffe6f2;
  --color-ink-subtle: #ffc2e2;
  --color-accent: #ffd600;
  --color-accent-subtle: #c2185b;
  --color-selection: #c2185b;
  background-image: linear-gradient(180deg, #ff2e88, #7c3aed 55%, #00b8d4);
}
[data-sidebar] a::before { content: "🧧 "; }
[data-sidebar] a:hover::before { content: "🎉 "; }
[data-sidebar] a[aria-current]::before, [data-sidebar] a[data-active]::before { content: "🌟 "; }
[data-shell-header] {
  background-image: repeating-linear-gradient(90deg, #ff6b6b 0 48px, #ffd93d 48px 96px, #6bcb77 96px 144px, #4d96ff 144px 192px, #c77dff 192px 240px);
  border-bottom: 4px dotted #ffd600;
}
h1::after { content: " 🌈✨"; }
h2::before { content: "🎊 "; }
h3::before { content: "🍀 "; }
[data-card]::before, [data-issue-row] td:first-child::before { content: "🧨 "; }
[data-card]:hover::before { content: "💥 "; }
[data-card] {
  background-image: linear-gradient(135deg, #fff8e1, #ffe4f1 50%, #e0f7ff);
  border: 2px solid #ff4fa3;
}
button, [role="button"] {
  border-radius: 999px;
  box-shadow: 0 0 0 2px #ffd600, 0 5px 0 #7c3aed;
  text-shadow: 0 1px 0 rgb(255 255 255 / 0.6);
}
button:hover, [role="button"]:hover { animation: lucky-bob 0.6s ease-in-out infinite; }
button:active, [role="button"]:active { box-shadow: 0 0 0 2px #ffd600, 0 1px 0 #7c3aed; transform: translateY(4px); }
input, select, textarea {
  border: 3px dashed #ff4fa3;
  background-image: linear-gradient(#ffffff, #fff0f6);
}
input:focus, select:focus, textarea:focus { border-style: solid; border-color: #ffd600; box-shadow: 0 0 0 4px rgb(255 214 0 / 0.5), 0 0 24px #ff2e88; }
th { background-image: linear-gradient(90deg, #ffd93d, #ff9ff3, #7afcff); }
tr:nth-child(odd) td { background-color: rgb(255 214 0 / 0.08); }
tr:nth-child(even) td { background-color: rgb(0 229 255 / 0.08); }
a:hover { text-decoration: underline wavy #ff2e88; }
[data-status] { animation: lucky-twinkle 2s ease-in-out infinite; }
::selection { background: #ffd600; color: #3b0764; }
[data-empty-state]::before { content: "🥟🍡🧋 "; font-size: 2rem; display: block; }
